class LoadScalarField(RootNode):

    def __init__(self, load_path : str, arrayName : str = ""):
        """
        Loads a scalar field from a file given at load_path.

        Args:
            load_path: The path to the scalar field that should be loaded.
            arrayName: The name of the array that should be loaded for the scalar field. If this is
                       left empty and the file only has one array, that single array will be used for the
                       scalar field.
        """

        super().__init__(load_path, Scalar, locals(), [arrayName])

        reader = vtk.vtkXMLImageDataReader()
        reader.SetFileName(self.check_file)
        reader.Update()

        image = reader.GetOutput()
        pd = image.GetPointData()
        numArrays = pd.GetNumberOfArrays()

        # if correctness_checks_on():
        if numArrays == 0:
            raise ValueError(f"File {load_path} has no arrays")
        elif numArrays == 1 and arrayName == "":
            arrayName = pd.GetArrayName(0)
        elif numArrays > 1:
            if arrayName == "":
                raise ValueError(f"The file {load_path} has multiple arrays and the user did not specify one. The user"\
                                " must specify if the data is scalar, vector, symmetric tensor, or asymmetric tensor data"\
                                " and which arrays they want to load.")

            if not pd.HasArray(arrayName):
                raise ValueError(f"File {load_path} has no array '{arrayName}'")

        self.arrayName = arrayName
        self._commit()

    @classmethod
    def chat_description(cls):
        return "queued loading scalar field"

    @classmethod
    def description(cls):
        return 'Loads a scalar field from a file given at load_path.'

    @classmethod
    def param_descriptions(cls):
        return {'load_path': 'The path to the scalar field that should be loaded. Time varying data is loaded by specifying a directory.',
         'arrayName': 'The name of the array that should be loaded for the scalar field. If '
                      'this is left empty and the file only has one array, that single array '
                      'will be used for the scalar field.'}

    def _evaluation_logic(self, filename):
        vti = XMLImageDataReader(FileName=[filename])
        vti.PointArrayStatus = [self.arrayName]
        vti.TimeArray = 'None'

        renameArrays = RenameArrays(Input=vti)
        renameArrays.PointArrays = [self.arrayName, 'Scalars_']
        return Scalar(renameArrays)

